const ICON_TAGS = new Set(["path", "circle", "rect", "line", "polyline", "polygon", "ellipse"])
const ICON_ATTRS = new Set(["d", "cx", "cy", "r", "rx", "ry", "x", "y", "x1", "x2", "y1", "y2", "width", "height", "points", "fill", "stroke", "stroke-width", "stroke-linecap", "stroke-linejoin", "fill-rule", "clip-rule", "opacity", "transform"])
const iconWarned = new Set()
export let iconNames = Object.freeze(Object.keys(ICONS))

export function registerIcons(icons) {
  const add = Object.entries(icons ?? {})
  for (const [name, nodes] of add) {
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(name)) throw new TypeError(`clanker-ui: icon name "${name}" must be lowercase words joined by "-"`)
    if (Object.hasOwn(ICONS, name) || Object.hasOwn(ICON_ALIASES, name)) throw new Error(`clanker-ui: icon "${name}" already exists`)
    const valid = n => typeof n === "string" || (Array.isArray(n) && ICON_TAGS.has(n[0]) && n[1] && typeof n[1] === "object" && Object.entries(n[1]).every(([k, v]) => ICON_ATTRS.has(k) && ["string", "number"].includes(typeof v)))
    if (!Array.isArray(nodes) || !nodes.length || !nodes.every(valid)) throw new TypeError(`clanker-ui: icon "${name}" must be a list of path strings or [tag, attrs] pairs (${[...ICON_TAGS].join(", ")})`)
  }
  for (const [name, nodes] of add) ICONS[name] = nodes.map(n => (typeof n === "string" ? n : [n[0], Object.fromEntries(Object.entries(n[1]).map(([k, v]) => [k, String(v)]))]))
  iconNames = Object.freeze(Object.keys(ICONS))
  const names = new Set(add.map(([name]) => name))
  for (const el of document.querySelectorAll("[data-lucide]")) {
    if (!names.has(el.getAttribute("data-lucide"))) continue
    try {
      fillIcon(el)
    } catch (err) {
      reportError(err)
    }
  }
}

