  if (open) toastState.above.add(el)
  else toastState.above.delete(el)
  if (!(el instanceof HTMLDialogElement)) return
  const i = toastModals.indexOf(el)
  if (i >= 0) toastModals.splice(i, 1)
  if (open) toastModals.push(el)
